    /**
     * Method to retrieve the Promotion via PromotionFetchOneSummary
     * @param 	summary PromotionFetchOneSummary 
     * @return 	PromotionFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Promotion getPromotion( PromotionFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "PromotionFetchOneSummary arg cannot be null" );
    	
    	Promotion entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Promotion
        	// --------------------------------------
        	CompletableFuture<Promotion> futureEntity = queryGateway.query(new FindPromotionQuery( new LoadPromotionFilter( summary.getPromotionId() ) ), ResponseTypes.instanceOf(Promotion.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Promotion with id " + summary.getPromotionId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


